// Build the Claude request from the exported Google Doc text.
const file = $('New doc in Project Alpha folder').first().json;
const text = $input.first().json.data || '';
const system = "You extract reusable knowledge from one project document for a company wiki.\nReturn ONLY a JSON object, no prose, no code fence:\n{\"card\": true|false, \"slug\": \"kebab-case-slug\", \"title\": \"...\", \"type\": \"learning|decision|risk\", \"date\": \"YYYY-MM-DD of the event\", \"owner_role\": \"PM|TL|Engineer|Team\", \"confidence\": \"high|medium|low\", \"context\": \"...\", \"what_happened\": \"...\", \"what_we_learned\": \"...\", \"reason_if_no_card\": \"...\"}\nRules:\n- One card for the single most reusable learning, decision or risk in the document. A status update that only restates a plan is not a learning: set \"card\": false.\n- Each of context, what_happened, what_we_learned: one or two plain sentences.\n- Redaction, before writing anything: never include names of people (use roles: PM, TL, Engineer, customer contact); contact data (phones, emails, addresses); health, leave, HR, performance or pay; dates of birth or personal identifiers; secrets (passwords, keys, tokens, VPN or Wi-Fi codes); customer identifiers (account numbers, household addresses); commercial terms (contract value, penalties, margins, disputes, vendor-switch talk).\n- If the learning cannot be written without one of these, set \"card\": false and \"reason_if_no_card\": \"dropped_confidential\".";
return [{ json: {
  fileId: file.id,
  fileName: file.name,
  body: {
    model: 'claude-haiku-5-5',
    max_tokens: 1024,
    system,
    messages: [{ role: 'user', content: `Document title: ${file.name}\n\n${text.slice(0, 60000)}` }]
  }
}}];

// Parse Claude's JSON, build the card in the repo's template, run the regex backstop.
const src = $('Build Claude request').first().json;
const raw = ($input.first().json.content || []).find(b => b.type === 'text')?.text || '{}';
let c;
try { c = JSON.parse(raw.replace(/^```(json)?|```$/g, '').trim()); }
catch (e) { return [{ json: { ok: false, reason: 'Claude did not return JSON', raw } }]; }
if (!c.card) return [{ json: { ok: false, reason: c.reason_if_no_card || 'no card', fileName: src.fileName } }];

const today = new Date().toISOString().slice(0, 10);
const date = /^\d{4}-\d{2}-\d{2}$/.test(c.date || '') ? c.date : today;
const slug = (c.slug || 'learning').toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
const id = `${date}-${slug}`;
const card = [
  '---',
  `id: ${id}`,
  `title: ${c.title}`,
  `type: ${c.type}`,
  'project: alpha',
  `date: ${date}`,
  `owner_role: ${c.owner_role}`,
  `confidence: ${c.confidence}`,
  'sensitivity: internal',
  `sources: [Google Drive: ${src.fileName}]`,
  'supersedes: none',
  '---',
  `**Context:** ${c.context}`,
  '',
  `**What happened:** ${c.what_happened}`,
  '',
  `**What we learned:** ${c.what_we_learned}`,
  ''
].join('\n');

// Same generic patterns as scripts/redaction_check.py in the repo.
const patterns = {
  email: /[\w.+-]+@[\w-]+\.[\w.-]+/g,
  phone: /(?<!\w)\+?\d[\d \-]{8,}\d(?!\w)/g,
  money: /[€$£]\s?\d[\d.,]*\s?[kKmM]?/g,
  secret_word: /\b(pass(word)?|pwd|api[_ -]?key|token|secret|vpn|wi-?fi|sftp)\b\s*[:=]/gi,
  dob: /\b(dob|date of birth|born)\b/gi,
  account_id: /\b[A-Z]{2,}-ACCT-\d+\b/g,
  hr_words: /\b(salary|raise|pip|performance improvement|sick|surgery|medical)\b/gi,
  commercial: /\b(margin|penalt(y|ies)|contract value|dispute|switch(ing)? vendor)\b/gi,
};
const hits = [];
for (const line of card.split('\n')) {
  if (line.startsWith('sources:')) continue;
  for (const [name, re] of Object.entries(patterns)) {
    for (const m of line.matchAll(re)) {
      if (name === 'phone' && /^\d{4}-\d{2}-\d{2}$/.test(m[0].trim())) continue;
      hits.push(`${name}: ${m[0]}`);
    }
  }
}
const stamp = new Date().toISOString().replace(/[-:]/g, '').slice(0, 13);
return [{ json: {
  ok: hits.length === 0,
  reason: hits.length ? 'redaction backstop hit' : '',
  hits,
  fileName: src.fileName,
  id, card,
  path: `learnings/approved/${id}.md`,
  branch: `capture/n8n-${stamp}`,
  contentB64: Buffer.from(card, 'utf8').toString('base64'),
}}];
